//! UniFFI bridge exposing [`client_core::ConstructEngine`] to Kotlin (DESIGN.md §2.4).
//!
//! Bindings are generated by `scripts/build_ffi.sh`. All exported methods are
//! synchronous (no async), so the generated Kotlin needs only JNA.

use std::sync::Arc;

use client_core::{ConstructEngine, EngineOptions, RedirectMode, StateSnapshot};

#[cfg(target_os = "android")]
mod android_log;

/// One-time per-process setup that the engine constructors run.
fn platform_init() {
    #[cfg(target_os = "android")]
    android_log::init();
}

/// A snapshot of engine state; JSON payloads are passed through as strings.
/// `seq` strictly increases per engine (drop snapshots with a seq not above
/// the last applied one); `pending_actions` counts unsent outbox rows.
/// `queries_json` is the bundle's `{query_key: [entity uri, ...]}` (`"{}"`
/// when none); `auth_json` is `{"state":"signed_out"|"pending"|"signed_in"|
/// "error","username"?,"error"?}`; `layout_json` is the layout on display,
/// `{"app_id","version"}` (`"{}"` while unknown or unversioned).
#[derive(uniffi::Record, Debug, Clone, PartialEq, Eq)]
pub struct FfiStateSnapshot {
    pub workspace_json: String,
    pub entities_json: String,
    pub is_online: bool,
    pub seq: u64,
    pub pending_actions: u32,
    pub queries_json: String,
    pub auth_json: String,
    pub layout_json: String,
    /// Data path loads: `{path: {"state", "error"?}}` (docs/DECISIONS.md D34).
    pub loads_json: String,
    /// Unread notifications (D52): `{"unread_total": n, "unread_by_app":
    /// {app_id: n}}`; zeros while signed out.
    pub notifications_json: String,
}

impl From<StateSnapshot> for FfiStateSnapshot {
    fn from(s: StateSnapshot) -> Self {
        Self {
            workspace_json: s.workspace_json,
            entities_json: s.entities_json,
            is_online: s.is_online,
            seq: s.seq,
            pending_actions: s.pending_actions,
            queries_json: s.queries_json,
            auth_json: s.auth_json,
            layout_json: s.layout_json,
            loads_json: s.loads_json,
            notifications_json: s.notifications_json,
        }
    }
}

/// An app catalog call failed (docs/DECISIONS.md D27, D32). `reason` is a
/// short sentence for the UI (e.g. "That version doesn't exist.").
#[derive(uniffi::Error, Debug, Clone, PartialEq, Eq)]
pub enum LayoutApiError {
    /// The pod could not be reached.
    Offline { reason: String },
    /// HTTP 401 (not expected: the app endpoints are public).
    Unauthorized { reason: String },
    /// HTTP 404 (unknown app or version).
    NotFound { reason: String },
    /// Any other failure; `status` 0 when there was no HTTP status.
    Server { status: u16, reason: String },
}

impl std::fmt::Display for LayoutApiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let (Self::Offline { reason }
        | Self::Unauthorized { reason }
        | Self::NotFound { reason }
        | Self::Server { reason, .. }) = self;
        f.write_str(reason)
    }
}

impl std::error::Error for LayoutApiError {}

impl From<client_core::LayoutApiError> for LayoutApiError {
    fn from(e: client_core::LayoutApiError) -> Self {
        use client_core::LayoutApiError as E;
        match e {
            E::Offline { reason } => Self::Offline { reason },
            E::Unauthorized { reason } => Self::Unauthorized { reason },
            E::NotFound { reason } => Self::NotFound { reason },
            E::Server { status, reason } => Self::Server { status, reason },
        }
    }
}

/// A photo could not be staged (`reason` is a short sentence for the user).
#[derive(Debug, uniffi::Error)]
pub enum AttachmentError {
    Failed { reason: String },
}

impl std::fmt::Display for AttachmentError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let Self::Failed { reason } = self;
        f.write_str(reason)
    }
}

impl std::error::Error for AttachmentError {}

/// Implemented on the Kotlin side. Called possibly from a background thread.
#[uniffi::export(callback_interface)]
pub trait StateObserver: Send + Sync {
    fn on_state_updated(&self, snapshot: FfiStateSnapshot);
}

/// Platform secure storage for the pod session (Android: Keystore-backed;
/// desktop: pass none and the engine uses the macOS Keychain). Called from
/// engine threads; an exception thrown here is contained (treated as
/// "nothing stored" / "not saved").
#[uniffi::export(callback_interface)]
pub trait SecureStore: Send + Sync {
    fn get(&self, key: String) -> Option<String>;
    fn set(&self, key: String, value: String);
    fn delete(&self, key: String);
}

/// Opens the sign-in URL in a browser; returns false if it could not.
/// Called on the engine's auth thread (not the UI thread); an exception
/// counts as false.
#[uniffi::export(callback_interface)]
pub trait UrlOpener: Send + Sync {
    fn open(&self, url: String) -> bool;
}

/// Gets each notification that arrives live while the engine's events
/// stream is open (D52), as `Notification` JSON (`{id, app_id, channel,
/// title, body, image_url?, target_uri?, group_key?, created_at, read}`), so
/// the platform can show it. Never called for notifications fetched by a
/// list call, replayed or passed to `handle_push_message`. Called on the
/// engine's events thread; an exception thrown here is contained.
#[uniffi::export(callback_interface)]
pub trait NotificationListener: Send + Sync {
    fn on_notification(&self, notification_json: String);
}

struct StoreAdapter(Box<dyn SecureStore>);

impl client_core::SecureStore for StoreAdapter {
    fn get(&self, key: &str) -> Option<String> {
        self.0.get(key.to_owned())
    }
    fn set(&self, key: &str, value: &str) {
        self.0.set(key.to_owned(), value.to_owned());
    }
    fn delete(&self, key: &str) {
        self.0.delete(key.to_owned());
    }
}

struct OpenerAdapter(Box<dyn UrlOpener>);

impl client_core::UrlOpener for OpenerAdapter {
    fn open(&self, url: &str) -> bool {
        self.0.open(url.to_owned())
    }
}

#[derive(uniffi::Object)]
pub struct EngineHandle {
    inner: Arc<ConstructEngine>,
}

#[uniffi::export]
impl EngineHandle {
    /// Engine for the `"home"` workspace. Returns immediately; the initial
    /// fetch runs on a background thread.
    #[uniffi::constructor]
    pub fn new(storage_path: String, base_url: String) -> Self {
        platform_init();
        Self {
            inner: Arc::new(ConstructEngine::init(&storage_path, &base_url)),
        }
    }

    /// Engine for an explicit workspace id.
    #[uniffi::constructor]
    pub fn new_with_workspace(
        storage_path: String,
        base_url: String,
        workspace_id: String,
    ) -> Self {
        platform_init();
        Self {
            inner: Arc::new(ConstructEngine::init_with_workspace(
                &storage_path,
                &base_url,
                &workspace_id,
            )),
        }
    }

    /// Engine with sign-in support. `secure_store`: None = the platform
    /// default (macOS Keychain; in-memory elsewhere). `url_opener`: None =
    /// sign-in reports "no browser available" and logs the URL.
    /// `redirect_uri`: None = loopback (`http://127.0.0.1:<port>/callback`),
    /// else a custom-scheme URI (e.g. `construct://oauth`) whose redirects the
    /// app passes to [`EngineHandle::handle_auth_redirect`].
    #[uniffi::constructor]
    pub fn new_with_options(
        storage_path: String,
        base_url: String,
        workspace_id: String,
        secure_store: Option<Box<dyn SecureStore>>,
        url_opener: Option<Box<dyn UrlOpener>>,
        redirect_uri: Option<String>,
    ) -> Self {
        platform_init();
        let options = EngineOptions {
            secure_store: secure_store
                .map(|s| Arc::new(StoreAdapter(s)) as Arc<dyn client_core::SecureStore>),
            url_opener: url_opener
                .map(|o| Arc::new(OpenerAdapter(o)) as Arc<dyn client_core::UrlOpener>),
            redirect: match redirect_uri.filter(|u| !u.trim().is_empty()) {
                Some(uri) => RedirectMode::Custom(uri),
                None => RedirectMode::Loopback,
            },
            ..EngineOptions::default()
        };
        Self {
            inner: Arc::new(ConstructEngine::init_with_options(
                &storage_path,
                &base_url,
                &workspace_id,
                options,
            )),
        }
    }

    /// Deliver an OAuth redirect URL (custom-scheme mode). True if it was
    /// taken: by the pending sign-in, or (none in memory, e.g. after a
    /// process restart) by a background completion of the persisted one
    /// (outcome in `auth_json`). Never blocks.
    pub fn handle_auth_redirect(&self, url: String) -> bool {
        self.inner.handle_auth_redirect(&url)
    }

    /// Sign out (non-blocking): forgets the session, notifies `signed_out`;
    /// the pod logout call and the refetch run in the background.
    pub fn logout(&self) {
        self.inner.logout();
    }

    /// Forget the session on this device only (Settings' "Leave pod", D46): no
    /// server call; private data purged and the workspace fetched again.
    pub fn forget_session(&self) {
        self.inner.forget_session();
    }

    /// Register an observer; it immediately receives the current snapshot.
    pub fn subscribe(&self, observer: Box<dyn StateObserver>) {
        self.inner
            .subscribe(move |s| observer.on_state_updated(s.into()));
    }

    /// Handle an `ActionIntent` JSON string. Never panics.
    pub fn dispatch(&self, intent_json: String) {
        self.inner.dispatch(&intent_json);
    }

    /// The current snapshot.
    pub fn snapshot(&self) -> FfiStateSnapshot {
        self.inner.snapshot().into()
    }

    /// Re-fetch the workspace on the calling thread (blocking), then notify.
    pub fn refresh(&self) {
        self.inner.refresh();
    }

    /// Stage a picked photo (D49): blocking (call off the UI thread). Returns
    /// JSON `{"id", "uri", "url", "width", "height"}`; the attachment's local
    /// entity (`uri`) is in the next snapshots.
    pub fn stage_attachment(&self, path: String) -> Result<String, AttachmentError> {
        let info = self
            .inner
            .stage_attachment(&path)
            .map_err(|reason| AttachmentError::Failed { reason })?;
        serde_json_string(&info).map_err(|reason| AttachmentError::Failed { reason })
    }

    /// Forget a staged photo the user removed before sending.
    pub fn discard_attachment(&self, id: String) {
        self.inner.discard_attachment(&id);
    }

    // App catalog (D27, D32). All blocking (call off the UI thread) and
    // read-only; each returns the pod's JSON body.

    /// The pod's apps (`GET /v1/apps`).
    pub fn list_apps(&self) -> Result<String, LayoutApiError> {
        Ok(self.inner.list_apps()?)
    }

    /// One page of an app's version history, newest first (`next_before`
    /// pages on; `limit` 1..=100, default 20).
    pub fn app_versions(
        &self,
        app_id: String,
        before: Option<i64>,
        limit: Option<u32>,
    ) -> Result<String, LayoutApiError> {
        Ok(self.inner.app_versions(&app_id, before, limit)?)
    }

    /// One version's metadata plus its full `layout`.
    pub fn app_version(&self, app_id: String, version: i64) -> Result<String, LayoutApiError> {
        Ok(self.inner.app_version(&app_id, version)?)
    }

    // Notifications (D52). The calls below are blocking (call them off the
    // UI thread) and return JSON. Without a session there are none: lists
    // are empty, counts zero, and the calls that need one fail
    // `Unauthorized`.

    /// Set (replace) the listener for notifications that arrive live.
    pub fn set_notification_listener(&self, listener: Box<dyn NotificationListener>) {
        self.inner.set_notification_listener(move |n| {
            listener.on_notification(serde_json::to_string(n).unwrap_or_default())
        });
    }

    /// What the pod shows for this device (`platform` e.g. "android",
    /// "desktop"; `name` e.g. the device model). Non-blocking.
    pub fn set_device_info(&self, platform: String, name: String) {
        self.inner.set_device_info(&platform, &name);
    }

    /// This installation's device id (stable across restarts).
    pub fn device_id(&self) -> String {
        self.inner.device_id()
    }

    /// One page of notifications, newest first: `{notifications: [...],
    /// unread_total, unread_by_app, next_before?}` (pass `next_before` as
    /// `before` for the next page; `limit` 0..=100). From the pod, else
    /// (unreachable) from the cache.
    pub fn list_notifications(
        &self,
        before: Option<String>,
        limit: u32,
        app_id: Option<String>,
    ) -> Result<String, LayoutApiError> {
        let list = self
            .inner
            .list_notifications(before.as_deref(), limit, app_id.as_deref())?;
        Ok(serde_json::to_string(&list).unwrap_or_default())
    }

    /// Mark notifications read (at once locally, then on the pod):
    /// `{unread_total, unread_by_app}`.
    pub fn mark_notifications_read(&self, ids: Vec<String>) -> Result<String, LayoutApiError> {
        let ev = self.inner.mark_notifications_read(&ids)?;
        Ok(serde_json::to_string(&ev).unwrap_or_default())
    }

    /// Mark every notification read (of one app, when given).
    pub fn mark_all_notifications_read(
        &self,
        app_id: Option<String>,
    ) -> Result<String, LayoutApiError> {
        let ev = self.inner.mark_all_notifications_read(app_id.as_deref())?;
        Ok(serde_json::to_string(&ev).unwrap_or_default())
    }

    /// `{"channels": [{app_id, id, title, description, default_enabled,
    /// importance, enabled}]}` with this device's choices.
    pub fn notification_channels(&self) -> Result<String, LayoutApiError> {
        Ok(self.inner.notification_channels()?)
    }

    /// Turn one of an app's channels on or off for this device.
    pub fn set_channel_enabled(
        &self,
        app_id: String,
        channel: String,
        enabled: bool,
    ) -> Result<(), LayoutApiError> {
        Ok(self.inner.set_channel_enabled(&app_id, &channel, enabled)?)
    }

    /// The server's VAPID public key (base64url) for a Web Push
    /// subscription; `NotFound` when the server sends no push.
    pub fn push_public_key(&self) -> Result<String, LayoutApiError> {
        Ok(self.inner.push_public_key()?)
    }

    /// Send this device's Web Push subscription to the pod (remembered and
    /// sent again after the next sign-in).
    pub fn register_push(
        &self,
        endpoint: String,
        p256dh: String,
        auth: String,
    ) -> Result<(), LayoutApiError> {
        Ok(self.inner.register_push(&endpoint, &p256dh, &auth)?)
    }

    /// Stop Web Push to this device.
    pub fn unregister_push(&self) -> Result<(), LayoutApiError> {
        Ok(self.inner.unregister_push()?)
    }

    /// A decrypted Web Push message body: cached, unread counts updated
    /// (observers notified); returns the `Notification` JSON, or None if
    /// the body is not a notification. Never calls the listener.
    pub fn handle_push_message(&self, payload_json: String) -> Option<String> {
        self.inner
            .handle_push_message(&payload_json)
            .map(|n| serde_json::to_string(&n).unwrap_or_default())
    }

    /// The sign-ins on this device's pod session (`GET /v1/auth/sign-ins`);
    /// `{"sign_ins":[]}` without a session.
    pub fn sign_ins(&self) -> Result<String, LayoutApiError> {
        Ok(self.inner.sign_ins()?)
    }
}

fn serde_json_string(info: &client_core::AttachmentInfo) -> Result<String, String> {
    client_core::attachment_info_json(info)
}

uniffi::setup_scaffolding!();

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;
    use std::sync::mpsc;
    use std::time::Duration;

    struct ChannelObserver(Mutex<mpsc::Sender<FfiStateSnapshot>>);

    impl StateObserver for ChannelObserver {
        fn on_state_updated(&self, snapshot: FfiStateSnapshot) {
            let _ = self.0.lock().unwrap().send(snapshot);
        }
    }

    #[test]
    fn offline_engine_notifies_observer_and_tolerates_garbage() {
        let dir = std::env::temp_dir().join(format!("client-ffi-test-{}", std::process::id()));
        let handle = EngineHandle::new(
            dir.to_string_lossy().into_owned(),
            "http://127.0.0.1:1".to_string(),
        );

        let (tx, rx) = mpsc::channel();
        handle.subscribe(Box::new(ChannelObserver(Mutex::new(tx))));

        let snap = rx
            .recv_timeout(Duration::from_secs(5))
            .expect("observer should receive a snapshot");
        assert!(!snap.is_online);

        // Blocking refresh against an unreachable server must not panic.
        handle.refresh();
        assert!(!handle.snapshot().is_online);

        handle.dispatch("not json".to_string());
        handle.dispatch(r#"{"type":"bogus"}"#.to_string());
        handle.dispatch(String::new());
        assert!(!handle.snapshot().is_online);

        // Catalog calls against an unreachable pod report Offline.
        assert!(matches!(
            handle.list_apps(),
            Err(LayoutApiError::Offline { .. })
        ));
        // No session: answered without a request.
        assert_eq!(handle.sign_ins().unwrap(), r#"{"sign_ins":[]}"#);
        assert!(matches!(
            handle.app_versions("home".into(), Some(3), Some(2)),
            Err(LayoutApiError::Offline { .. })
        ));
        assert!(matches!(
            handle.app_version("home".into(), 1),
            Err(LayoutApiError::Offline { .. })
        ));

        // Notifications: signed out there are none, and no errors.
        assert_eq!(
            handle.list_notifications(None, 20, None).unwrap(),
            r#"{"notifications":[],"unread_total":0,"unread_by_app":{}}"#
        );
        assert_eq!(
            handle.notification_channels().unwrap(),
            r#"{"channels":[]}"#
        );
        assert!(matches!(
            handle.push_public_key(),
            Err(LayoutApiError::Unauthorized { .. })
        ));
        assert_eq!(handle.handle_push_message("nope".into()), None);
        assert_eq!(handle.device_id(), handle.device_id());
        assert!(handle.device_id().len() >= 8);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn new_with_workspace_constructs() {
        let handle = EngineHandle::new_with_workspace(
            String::new(),
            "http://127.0.0.1:1".to_string(),
            "other".to_string(),
        );
        let snap = handle.snapshot();
        assert!(!snap.is_online);
    }

    #[test]
    fn snapshot_carries_seq_and_pending_actions() {
        let handle = EngineHandle::new(String::new(), "http://127.0.0.1:1".to_string());
        let before = handle.snapshot();
        assert_eq!(before.pending_actions, 0);
        handle.dispatch(
            r#"{"intent":"action.mutation.optimistic","entity_uri":"core://counters/home","field":"count","value_expr":"entity.count + 1","rollback_value":0,"endpoint":"/v1/counters/home/increment","payload":{}}"#
                .to_string(),
        );
        let after = handle.snapshot();
        assert_eq!(after.pending_actions, 1);
        assert!(after.seq > before.seq);
    }

    struct PanickyStore;
    impl SecureStore for PanickyStore {
        fn get(&self, _key: String) -> Option<String> {
            panic!("store exploded")
        }
        fn set(&self, _key: String, _value: String) {
            panic!("store exploded")
        }
        fn delete(&self, _key: String) {
            panic!("store exploded")
        }
    }

    struct PanickyOpener;
    impl UrlOpener for PanickyOpener {
        fn open(&self, _url: String) -> bool {
            panic!("opener exploded")
        }
    }

    #[test]
    fn new_with_options_survives_panicking_callbacks() {
        let handle = EngineHandle::new_with_options(
            String::new(),
            "http://127.0.0.1:1".to_string(),
            "pixelfed_home".to_string(),
            Some(Box::new(PanickyStore)),
            Some(Box::new(PanickyOpener)),
            Some("construct://oauth".to_string()),
        );
        assert_eq!(handle.snapshot().auth_json, r#"{"state":"signed_out"}"#);
        // Taken for the persisted-flow check (the store panics: nothing matches).
        assert!(handle.handle_auth_redirect("construct://oauth?code=x&state=y".to_string()));
        handle.logout();
        // Sign-in against an unreachable pod ends in the error state.
        handle.dispatch(
            r#"{"intent":"action.auth.login","instance_url":"http://127.0.0.1:1",
                "app_path":"/v1/auth/pixelfed/app","token_path":"/v1/auth/pixelfed/token"}"#
                .to_string(),
        );
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            let auth = handle.snapshot().auth_json;
            if auth.contains("\"error\"")
                && auth.contains(client_core::auth::SIGN_IN_POD_UNREACHABLE)
            {
                break;
            }
            assert!(std::time::Instant::now() < deadline, "auth_json: {auth}");
            std::thread::sleep(Duration::from_millis(20));
        }
    }

    #[test]
    fn snapshot_carries_queries_and_auth_json() {
        let handle = EngineHandle::new(String::new(), "http://127.0.0.1:1".to_string());
        let snap = handle.snapshot();
        assert_eq!(snap.queries_json, "{}");
        assert_eq!(snap.auth_json, r#"{"state":"signed_out"}"#);

        let core = StateSnapshot {
            workspace_json: "null".into(),
            entities_json: "{}".into(),
            is_online: true,
            seq: 7,
            pending_actions: 2,
            queries_json: r#"{"timeline:home":["pixelfed://posts/1"]}"#.into(),
            auth_json: r#"{"state":"signed_in","username":"a"}"#.into(),
            layout_json: r#"{"app_id":"home","version":5}"#.into(),
            loads_json: r#"{"/v1/x":{"state":"ready"}}"#.into(),
            notifications_json: r#"{"unread_total":1,"unread_by_app":{"a":1}}"#.into(),
        };
        let ffi: FfiStateSnapshot = core.clone().into();
        assert_eq!(ffi.queries_json, core.queries_json);
        assert_eq!(ffi.auth_json, core.auth_json);
        assert_eq!(ffi.layout_json, core.layout_json);
        assert_eq!(ffi.loads_json, core.loads_json);
        assert_eq!(ffi.notifications_json, core.notifications_json);
        assert_eq!(
            snap.notifications_json,
            r#"{"unread_by_app":{},"unread_total":0}"#
        );
        assert_eq!(snap.layout_json, "{}");
        assert_eq!(snap.loads_json, "{}");
        assert_eq!((ffi.seq, ffi.pending_actions), (7, 2));
    }
}
